{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.website_marketplace_fact_items_intermediate as With Order_Master as ( Select * from ( select om.*,decline_reason ,case when not(lower(ifnull(om.del_firstname,\'\')) LIKE \'%test%\' OR lower(ifnull(om.del_lastname,\'\')) LIKE \'%test%\') AND ifnull(om.current_status,0) != 16 AND ifnull(om.parent_order_id,1) = 0 then 1 else 0 end as Order_Date_Flag ,case when ifnull(parent_order_id,1) = 0 AND ifnull(om.master_order_id,1) = 0 then 1 else 0 end as Paid_date_Flag ,case when lower(discount_type) like \'%fixed%\' or trim(discount_type) = \'\' then discount else (discount/100) * sub_total end calculated_discount ,row_number() over(partition by om.order_id order by 1) rw from cc_comfort_db.order_master om left join ( select order_id,decline_reason from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on op.order_id = om.order_id where not(lower(ifnull(decline_reason,\'\')) like \'%test order%\') and cast(ifnull(order_total,1) as int64) > 0 and trim(ifnull(payment_gateway,\'\')) !=\'\' and not(ifnull(current_status,1) in (0,25)) and domain_id != 220 )where rw = 1 ) , Product_Level_Data as ( select om.* ,case when af_order_id is not null then \'Affiliates\' end as Affiliates ,aff_net_name ,od.site_product_name ,od.product_name ,od.product_qty ,od.product_pack ,od.cost_price ,ifnull(prod_ship,0) prod_ship , 0 as sales_conversion_flag ,(ifnull(selling_price,0)*ifnull(product_qty,0)) as Selling_Price_pre ,od.unit_equi_pound * ifnull(product_qty,0) + ifnull(prod_ship,0) as total_price ,case when ifnull(od.prod_vat_amazon,0) != 0 then ifnull(od.prod_vat_amazon,0) else ifnull(od.prod_vat,0) end as TAX ,od.is_pack ,od.status ,od.returnreason ,od.product_id ,od.product_master_id ,od.other_vat_charge ,od.prod_refund_vat ,od.primary_cat_id ,od.product_code as sku ,del_country as delivery_country ,case when upper(`pg_status`) = \'Y\' AND pg.`mpg_id` = 11 then \'MARKETPLACE\' else \'WEBSITE\' end as Business_Segment ,ifnull(cost_price ,0) * ifnull(product_qty,0) as Product_Cost ,safe_divide(ifnull(calculated_discount,0), count(*) over(partition by om.order_id)) as calculated_discount_final ,safe_divide(ifnull(additional_added_amount,0), count(*) over(partition by om.order_id)) as additional_amount_pre ,safe_divide(ifnull(shipping_cost,0), count(*) over(partition by om.order_id)) as shipping_price ,null as prod_refund_amount_local from Order_Master om left join cc_comfort_db.order_details od on od.order_id = om.order_id left join ( SELECT * FROM `cc_comfort_db.payment_gateways` qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on replace(lower(trim(ifnull(pg.gateway_name,\'\'))),\' \',\'\') = replace(lower(trim(ifnull(om.payment_gateway,\'\'))),\' \',\'\') left join ( select order_id af_order_id,aff_net_name from cc_comfort_db.affiliates_network_sales_track_data s left join ( select distinct aff_net_id,aff_net_name from cc_comfort_db.affiliates_network )m on cast(s.order_network as int64) = (cast(m.aff_net_id as int64)) qualify row_number() over(partition by order_id order by 1) = 1 and lower(ifnull(order_status,\'\')) in (\'approved\',\'pending\') )aff on aff.af_order_id = om.order_id where (ifnull(od.status,0)) = 1 ) select pld.order_id ,pld.transaction_id ,pld.Order_Date_Flag ,pld.Paid_date_Flag ,sales_conversion_flag ,pld.order_channel ,pld.cust_id ,pld.order_id as reference_code ,coalesce(del_mobile,bill_mobile) as phone ,cast(null as string) as email ,cast(null as string) as name ,date(pld.order_date) as order_date ,timestamp(pld.order_date) as order_timestamp ,date(pld.order_modified_date) as order_modified_date ,currency currency_code ,coalesce(del_city,bill_city) as City ,coalesce(del_state,bill_State) as State ,coalesce(del_zipcode,bill_zipcode) zipcode ,upper(coalesce(del_country,bill_country)) as country_name ,aff_net_name ,Affiliates ,pld.payment_gateway ,delivery_country ,courier_name ,pld.courier_id ,tracking_number as awb ,site_product_name ,sku ,product_name ,product_qty ,product_pack ,cost_price ,Selling_Price_pre ,total_price ,TAX ,pld.calculated_discount_final as discount_pre ,pld.additional_amount_pre ,shipping_price ,is_pack ,status ,returnreason ,product_id ,pld.product_master_id ,other_vat_charge ,prod_refund_amount_local ,prod_refund_vat ,primary_cat_id ,upper(cd.cd_name) product_category_local_payment ,upper(cd.cm_name) product_category_payment ,pg.pg_status ,pg.mpg_id ,pg.merchant_fee ,pg.marketplaces_commission ,Business_Segment ,case when Business_Segment = \'WEBSITE\' then \'WEBSITE\' else pgmm.Marketplace end as Marketplace ,case when Business_Segment = \'WEBSITE\' then d.brand else pmi.pb_name end as Brand ,pg.mpg_name as mpg_Name_Category ,d.id as domain_id ,upper(d.domain_division) domain_division ,date(op.paid_date) as paid_date ,date(op.dispatched_date) as dispatched_date ,date(op.decline_date) as decline_date ,op.decline_reason ,date(op.refund_date) as refund_date ,op.refund_reason ,op.refund_amount ,op.refund_gateway ,csg.Status_Name Order_Status ,d.name as domain_name ,d.abbr as Region ,category_name.cm_name as Product_Category ,sub_category.cm_name as Product_Sub_Category ,Product_Cost ,ifnull(Other_Cost,0) * ifnull(product_qty,0) as Product_Other_Cost ,prod_ship ,exchange_rate ,order_total from Product_Level_Data pld left join( select * from cc_comfort_db.category_domain cd left join ( select * from `cc_comfort_db.category_master` qualify ROW_NUMBER() over(partition by ifnull(cm_id,0) order by 1) = 1 )cm on cm.cm_id = cd.cd_cm_id qualify ROW_NUMBER() over(partition by ifnull(cd_id,0) order by 1) = 1 )cd on cd.cd_id = pld.primary_cat_id left join ( SELECT pg.*,pg_category.mpg_name FROM `cc_comfort_db.payment_gateways` pg left join ( select * from powerbi-425707.cc_comfort_db.master_payment_gateway qualify ROW_NUMBER() over(partition by (ifnull(mpg_id,0)) order by 1) = 1 )pg_category on pg_category.mpg_id = pg.mpg_id qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on lower(pg.gateway_name) = lower(pld.payment_gateway) left join ( select payment_gateway,Marketplace from `MAPLEMONK.PaymentGateway_to_Marketplace_mapping` qualify ROW_NUMBER() over(partition by lower(ifnull(payment_gateway,\'\')) order by 1) = 1 )pgmm on lower(pgmm.payment_gateway) = lower(pld.payment_gateway) left join ( select domain_division,name,d.id,default_country_code,group_id,brand,abbr from cc_comfort_db.domains d left join ( select Domain_Name,brand from `MAPLEMONK.Domain_Marketplace_Mapping` qualify ROW_NUMBER() over(partition by lower(ifnull(Domain_Name,\'\')) order by 1) = 1 and lower(Marketplace) = \'website\' )dnm on lower(dnm.Domain_Name) = lower(d.name) left join ( select id,abbr from cc_comfort_db.domains_group qualify ROW_NUMBER() over(partition by (ifnull(id,0)) order by 1) = 1 )dg on dg.id = d.group_id qualify ROW_NUMBER() over(partition by (ifnull(d.id,0)) order by 1) = 1 )d on pld.domain_id = d.id left join ( select * from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on op.order_id = pld.order_id left join ( select * from maplemonk.current_status_mapping csg qualify ROW_NUMBER() over(partition by ifnull(cast(id as int64),0) order by 1) = 1 )csg on cast(csg.id as string) = cast(pld.current_status as string) left join ( select product_master_id ,pb_name from cc_comfort_db.products_master pm left join cc_comfort_db.product_brands pb on lower(cast(pm.pm_pb_brand_id as string)) = lower(cast(pb.pb_brand_id as string)) qualify row_number() over(partition by product_master_id order by 1) = 1 )pmi on lower(cast(pmi.product_master_id as string)) = lower(cast(pld.product_master_id as string)) left join ( select pmc_pm_id ,pmc_type ,cm.cm_name from cc_comfort_db.product_master_category pmc left join cc_comfort_db.category_master cm on pmc.pmc_cm_id = cm.cm_id qualify row_number() over(partition by pmc_pm_id,pmc_type order by pmc_pm_id asc) = 1 )category_name on category_name.pmc_pm_id = pld.product_master_id and lower(category_name.pmc_type) = \'p\' left join ( select pmc_pm_id ,pmc_type ,cm.cm_name from cc_comfort_db.product_master_category pmc left join cc_comfort_db.category_master cm on pmc.pmc_cm_id = cm.cm_id qualify row_number() over(partition by pmc_pm_id,pmc_type order by pmc_pm_id asc) = 1 )sub_category on sub_category.pmc_pm_id = pld.product_master_id and lower(sub_category.pmc_type) = \'s\' left join ( select product_master_id pod_product_master_id ,cast(stock_date as date) as stock_Date ,Sum(ifnull(other_cost ,0)) as Other_Cost from cc_comfort_db.stock_report sr left join ( select stockid,product_master_id from cc_comfort_db.stock qualify row_number() over(partition by stockid order by 1) = 1 )s on sr.stockid = s.stockid group by 1,2 ) pod on cast(pod.pod_product_master_id as string) = cast(pld.product_master_id as string) and cast(pod.stock_Date as date) = cast(pld.order_date as date) ; CREATE OR REPLACE TABLE maplemonk.website_marketplace_fact_items AS Select mc.*, ifnull(mc.prod_refund_amount_local,0)/ifnull(rh.er_exchange_rate,1) as prod_refund_amount, case when ifnull(exchange_rate,0) > 0 then ifnull(mc.additional_amount_pre,0)/ifnull(exchange_rate,1) else ifnull(mc.additional_amount_pre,0)/ifnull(rh.er_exchange_rate,1) end as additional_amount, case when ifnull(exchange_rate,0) > 0 then ifnull(mc.discount_pre,0)/ifnull(exchange_rate,1) else ifnull(mc.discount_pre,0)/ifnull(rh.er_exchange_rate,1) end as Discount, case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(selling_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(selling_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(selling_price_pre,0) end as selling_price_check, (case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(selling_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(selling_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(selling_price_pre,0) end) + ifnull(case when ifnull(exchange_rate,0) > 0 then ifnull(mc.additional_amount_pre,0)/ifnull(exchange_rate,1) else ifnull(mc.additional_amount_pre,0)/ifnull(rh.er_exchange_rate,1) end ,0) - ifnull(case when ifnull(exchange_rate,0) > 0 then ifnull(mc.discount_pre,0)/ifnull(exchange_rate,1) else ifnull(mc.discount_pre,0)/ifnull(rh.er_exchange_rate,1) end ,0) + ifnull(prod_ship,0) as Selling_Price from maplemonk.website_marketplace_fact_items_intermediate mc left join `cc_comfort_db.exchange_rate_history` rh on cast(rh.er_date as date) = cast(mc.order_date as date) and upper(mc.currency_code) = upper(rh.er_currency_name) ; create or replace table maplemonk.chargeback_fact_itmes as select coalesce(lost_chargeback_date,won_chargeback_date) as date ,coalesce(lc.marketplace,wc.marketplace) as marketplace ,coalesce(lc.region,wc.region) as region ,ifnull(lc.chargeback,0) - ifnull(wc.chargeback,0) as chargeback from ( select cast(op.lost_chargeback_date as date) lost_chargeback_date ,upper(WM.marketplace) marketplace ,upper(region) region ,sum(ifnull(chargeback,0)) chargeback from cc_comfort_db.order_processing op left join ( select order_id , Marketplace, region, safe_divide(order_total,ifnull(exchange_rate,1)) as chargeback from maplemonk.website_marketplace_fact_items qualify row_number() over(partition by order_id order by 1) = 1 )WM on op.order_id = wm.order_id where lost_chargeback_date is not null group by 1,2,3 )lc full outer join ( select cast(op.won_chargeback_date as date) won_chargeback_date ,upper(WM.marketplace) marketplace ,upper(region) region ,sum(ifnull(chargeback,0)) chargeback from cc_comfort_db.order_processing op left join ( select order_id , Marketplace, region, safe_divide(order_total,ifnull(exchange_rate,1)) as chargeback from maplemonk.website_marketplace_fact_items qualify row_number() over(partition by order_id order by 1) = 1 )WM on op.order_id = wm.order_id where won_chargeback_date is not null group by 1,2,3 )wc on lc.lost_chargeback_date = wc.won_chargeback_date and lower(lc.marketplace) = lower(wc.marketplace) and lower(lc.region) = lower(wc.region) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

